def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == 5 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            # The large 5-colored figure is recolored to match the neighboring 2 figure.
            if len(component) > 1:
                for y, x in component:
                    out[y][x] = 2
    return out
